-- Tycoon database setup (generated by db/bundle.mjs from db/migrations — do not edit by hand).
-- Paste this whole file into the Supabase SQL editor and press Run.
-- Safe to run again after updating: tables are kept, functions are replaced.

-- >>> 001_schema.sql
-- =====================================================================
-- Tycoon: schema
-- Everything lives in the `tycoon` schema, which is NOT exposed over the
-- Supabase REST API. Clients can only reach the game through the
-- `public.tycoon_*` functions defined in 003_api.sql.
-- This file is idempotent: running it again is safe.
-- =====================================================================

CREATE SCHEMA IF NOT EXISTS extensions;
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
CREATE SCHEMA IF NOT EXISTS tycoon;

-- Economic rulesets. All rates, tax bases, valuation formulas and cadence
-- live in `config`. A new economic model is an INSERT, not a code change.
CREATE TABLE IF NOT EXISTS tycoon.rulesets (
  id           TEXT PRIMARY KEY,
  name         TEXT NOT NULL,
  description  TEXT NOT NULL,
  config       JSONB NOT NULL
);

CREATE TABLE IF NOT EXISTS tycoon.worlds (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  slug         TEXT NOT NULL UNIQUE,
  name         TEXT NOT NULL,
  ruleset_id   TEXT NOT NULL REFERENCES tycoon.rulesets(id),
  status       TEXT NOT NULL DEFAULT 'running'
               CHECK (status IN ('open','running','ended')),
  started_at   TIMESTAMPTZ DEFAULT now(),
  ends_at      TIMESTAMPTZ,
  tick_count   INT NOT NULL DEFAULT 0,
  next_tick_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Login accounts: plain username + password (bcrypt via pgcrypto).
-- IP addresses are recorded from the request headers when available.
CREATE TABLE IF NOT EXISTS tycoon.accounts (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  username      TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_ip    TEXT,
  last_ip       TEXT,
  last_login_at TIMESTAMPTZ
);
CREATE UNIQUE INDEX IF NOT EXISTS accounts_username_key
  ON tycoon.accounts (lower(username));

CREATE TABLE IF NOT EXISTS tycoon.sessions (
  token        TEXT PRIMARY KEY,
  account_id   UUID NOT NULL REFERENCES tycoon.accounts(id) ON DELETE CASCADE,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  ip           TEXT
);

-- A player is an account's presence in one world.
CREATE TABLE IF NOT EXISTS tycoon.players (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  world_id     UUID NOT NULL REFERENCES tycoon.worlds(id),
  account_id   UUID NOT NULL REFERENCES tycoon.accounts(id),
  handle       TEXT NOT NULL,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (world_id, account_id),
  UNIQUE (world_id, handle)
);

-- A parcel is one real street: all same-named, connected OSM ways merged.
-- Geometry is stored as JSON line parts ([[[lon,lat],...], ...]) so the
-- schema has no PostGIS dependency and runs on any Postgres (incl. PGlite).
CREATE TABLE IF NOT EXISTS tycoon.parcels (
  id                 BIGSERIAL PRIMARY KEY,
  world_id           UUID NOT NULL REFERENCES tycoon.worlds(id),
  name               TEXT NOT NULL,
  suburb             TEXT,
  osm_way_ids        BIGINT[] NOT NULL,
  geom               JSONB NOT NULL,
  c_lon              DOUBLE PRECISION NOT NULL,
  c_lat              DOUBLE PRECISION NOT NULL,
  min_lon            DOUBLE PRECISION NOT NULL,
  min_lat            DOUBLE PRECISION NOT NULL,
  max_lon            DOUBLE PRECISION NOT NULL,
  max_lat            DOUBLE PRECISION NOT NULL,
  length_m           DOUBLE PRECISION NOT NULL CHECK (length_m > 0),
  highway_class      TEXT NOT NULL,
  slots_total        INT NOT NULL CHECK (slots_total >= 1),
  density_weight     NUMERIC NOT NULL,
  land_value         BIGINT NOT NULL CHECK (land_value >= 0),  -- assessed, mutable by tick
  improvement_value  BIGINT NOT NULL DEFAULT 0,                -- derived from improvements
  owner_id           UUID REFERENCES tycoon.players(id),
  acquired_at        TIMESTAMPTZ,
  lease_expires_at   TIMESTAMPTZ,                              -- NULL under freehold
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS parcels_ways_idx  ON tycoon.parcels USING GIN (osm_way_ids);
CREATE INDEX IF NOT EXISTS parcels_box_idx   ON tycoon.parcels
  USING GIST (box(point(min_lon, min_lat), point(max_lon, max_lat)));
CREATE INDEX IF NOT EXISTS parcels_owner_idx ON tycoon.parcels (world_id, owner_id);
CREATE INDEX IF NOT EXISTS parcels_lat_idx   ON tycoon.parcels (world_id, c_lat);
CREATE INDEX IF NOT EXISTS parcels_name_idx  ON tycoon.parcels (world_id, lower(name));

CREATE TABLE IF NOT EXISTS tycoon.building_types (
  id           TEXT PRIMARY KEY,
  name         TEXT NOT NULL,
  description  TEXT NOT NULL DEFAULT '',
  cost         BIGINT NOT NULL CHECK (cost > 0),
  slots_used   INT NOT NULL CHECK (slots_used >= 1),
  -- Multiplier (basis points, 10000 = 1x) applied to the ruleset's
  -- income.from_improvements_bp for buildings of this type.
  yield_bp     INT NOT NULL CHECK (yield_bp >= 0),
  sort_order   INT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS tycoon.improvements (
  id           BIGSERIAL PRIMARY KEY,
  parcel_id    BIGINT NOT NULL REFERENCES tycoon.parcels(id),
  type_id      TEXT NOT NULL REFERENCES tycoon.building_types(id),
  cost         BIGINT NOT NULL,   -- snapshot at build time
  slots_used   INT NOT NULL,      -- snapshot at build time
  slot_index   INT NOT NULL,      -- first slot occupied along the street
  built_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS improvements_parcel_idx ON tycoon.improvements (parcel_id);

CREATE TABLE IF NOT EXISTS tycoon.ticks (
  id               BIGSERIAL PRIMARY KEY,
  world_id         UUID NOT NULL REFERENCES tycoon.worlds(id),
  tick_number      INT NOT NULL,
  ran_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
  ruleset_snapshot JSONB NOT NULL
);
CREATE INDEX IF NOT EXISTS ticks_world_idx ON tycoon.ticks (world_id, id DESC);

-- Append only. No UPDATE, no DELETE, ever (enforced by trigger below).
-- Balances are always derived from this table.
CREATE TABLE IF NOT EXISTS tycoon.ledger (
  id            BIGSERIAL PRIMARY KEY,
  world_id      UUID NOT NULL REFERENCES tycoon.worlds(id),
  tick_id       BIGINT REFERENCES tycoon.ticks(id),
  from_account  TEXT NOT NULL,   -- 'bank' | 'treasury' | 'player:<uuid>'
  to_account    TEXT NOT NULL,
  amount        BIGINT NOT NULL CHECK (amount > 0),
  reason        TEXT NOT NULL,   -- 'purchase'|'build'|'income:*'|'tax:*'|'loan'|...
  parcel_id     BIGINT REFERENCES tycoon.parcels(id),
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (from_account <> to_account)
);
CREATE INDEX IF NOT EXISTS ledger_from_idx ON tycoon.ledger (world_id, from_account);
CREATE INDEX IF NOT EXISTS ledger_to_idx   ON tycoon.ledger (world_id, to_account);
CREATE INDEX IF NOT EXISTS ledger_tick_idx ON tycoon.ledger (tick_id);

CREATE OR REPLACE FUNCTION tycoon.ledger_append_only() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'ledger_is_append_only';
END $$;

DROP TRIGGER IF EXISTS ledger_no_update ON tycoon.ledger;
CREATE TRIGGER ledger_no_update BEFORE UPDATE OR DELETE ON tycoon.ledger
  FOR EACH ROW EXECUTE FUNCTION tycoon.ledger_append_only();
DROP TRIGGER IF EXISTS ledger_no_truncate ON tycoon.ledger;
CREATE TRIGGER ledger_no_truncate BEFORE TRUNCATE ON tycoon.ledger
  FOR EACH STATEMENT EXECUTE FUNCTION tycoon.ledger_append_only();

CREATE OR REPLACE VIEW tycoon.balances AS
SELECT world_id, account, SUM(delta)::BIGINT AS balance FROM (
  SELECT world_id, to_account   AS account,  amount AS delta FROM tycoon.ledger
  UNION ALL
  SELECT world_id, from_account AS account, -amount AS delta FROM tycoon.ledger
) t GROUP BY world_id, account;

-- Public activity feed ("alice bought Oxford Street").
CREATE TABLE IF NOT EXISTS tycoon.events (
  id          BIGSERIAL PRIMARY KEY,
  world_id    UUID NOT NULL REFERENCES tycoon.worlds(id),
  player_id   UUID REFERENCES tycoon.players(id),
  kind        TEXT NOT NULL,
  parcel_id   BIGINT REFERENCES tycoon.parcels(id),
  data        JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS events_world_idx ON tycoon.events (world_id, id DESC);

-- >>> 002_functions.sql
-- =====================================================================
-- Tycoon: core game functions (internal, schema `tycoon`).
-- These are never callable by clients directly; the SECURITY DEFINER
-- wrappers in 003_api.sql authenticate the caller and then call these.
-- =====================================================================

-- Basis-point maths: floor(amount * bp / 10000). The only place the
-- basis-point divisor appears.
CREATE OR REPLACE FUNCTION tycoon.apply_bp(p_amount NUMERIC, p_bp NUMERIC)
RETURNS BIGINT LANGUAGE sql IMMUTABLE AS $$
  SELECT floor(COALESCE(p_amount, 0) * COALESCE(p_bp, 0) / 10000)::BIGINT
$$;

-- Great-circle distance in metres.
CREATE OR REPLACE FUNCTION tycoon.geo_dist_m(lat1 DOUBLE PRECISION, lon1 DOUBLE PRECISION,
                                             lat2 DOUBLE PRECISION, lon2 DOUBLE PRECISION)
RETURNS DOUBLE PRECISION LANGUAGE sql IMMUTABLE AS $$
  SELECT 2 * 6371008.8 * asin(sqrt(
    power(sin(radians(lat2 - lat1) / 2), 2) +
    cos(radians(lat1)) * cos(radians(lat2)) * power(sin(radians(lon2 - lon1) / 2), 2)
  ))
$$;

-- Metres -> degrees of latitude (for cheap bounding-box prefilters).
CREATE OR REPLACE FUNCTION tycoon.metres_to_lat_deg(p_m DOUBLE PRECISION)
RETURNS DOUBLE PRECISION LANGUAGE sql IMMUTABLE AS $$ SELECT p_m / 111320.0 $$;

CREATE OR REPLACE FUNCTION tycoon.world_config(p_world UUID)
RETURNS JSONB LANGUAGE sql STABLE AS $$
  SELECT r.config FROM tycoon.worlds w JOIN tycoon.rulesets r ON r.id = w.ruleset_id
  WHERE w.id = p_world
$$;

CREATE OR REPLACE FUNCTION tycoon.balance_of(p_world UUID, p_account TEXT)
RETURNS BIGINT LANGUAGE sql STABLE AS $$
  SELECT (COALESCE((SELECT SUM(amount) FROM tycoon.ledger
                    WHERE world_id = p_world AND to_account = p_account), 0)
        - COALESCE((SELECT SUM(amount) FROM tycoon.ledger
                    WHERE world_id = p_world AND from_account = p_account), 0))::BIGINT
$$;

CREATE OR REPLACE FUNCTION tycoon.player_account(p_player UUID)
RETURNS TEXT LANGUAGE sql IMMUTABLE AS $$ SELECT 'player:' || p_player::TEXT $$;

-- Outstanding starting loan = loans issued - repayments.
CREATE OR REPLACE FUNCTION tycoon.loan_outstanding(p_world UUID, p_player UUID)
RETURNS BIGINT LANGUAGE sql STABLE AS $$
  SELECT (COALESCE((SELECT SUM(amount) FROM tycoon.ledger
                    WHERE world_id = p_world AND to_account = tycoon.player_account(p_player)
                      AND reason = 'loan'), 0)
        - COALESCE((SELECT SUM(amount) FROM tycoon.ledger
                    WHERE world_id = p_world AND from_account = tycoon.player_account(p_player)
                      AND reason = 'loan_repayment'), 0))::BIGINT
$$;

-- ---------------------------------------------------------------------
-- Whitelisted expression compiler.
-- Turns a ruleset formula such as "land_value + improvement_value" into a
-- SQL fragment over the per-parcel variables relation `v`. Only allowed
-- identifiers, numeric literals, + - * / and parentheses are accepted;
-- anything else raises. Tokens are re-emitted separated by spaces, so no
-- token sequence can form a comment or any other SQL syntax.
-- ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION tycoon.compile_expr(p_expr TEXT, p_allowed TEXT[])
RETURNS TEXT LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
  rest TEXT := COALESCE(p_expr, '');
  tok TEXT;
  out TEXT := '';
  expect_operand BOOLEAN := true;
  depth INT := 0;
BEGIN
  IF length(rest) > 500 THEN
    RAISE EXCEPTION 'expr_too_long';
  END IF;
  LOOP
    rest := regexp_replace(rest, '^\s+', '');
    EXIT WHEN rest = '';
    tok := substring(rest FROM '^[A-Za-z_][A-Za-z0-9_]*');
    IF tok IS NOT NULL THEN
      IF NOT expect_operand THEN RAISE EXCEPTION 'expr_syntax: unexpected %', tok; END IF;
      IF NOT (tok = ANY (p_allowed)) THEN
        RAISE EXCEPTION 'expr_identifier_not_allowed: %', tok;
      END IF;
      out := out || ' v.' || tok;
      expect_operand := false;
    ELSE
      tok := substring(rest FROM '^[0-9]+(?:\.[0-9]+)?');
      IF tok IS NOT NULL THEN
        IF NOT expect_operand THEN RAISE EXCEPTION 'expr_syntax: unexpected %', tok; END IF;
        out := out || ' ' || tok || '::numeric';
        expect_operand := false;
      ELSE
        tok := substr(rest, 1, 1);
        IF tok = '(' THEN
          IF NOT expect_operand THEN RAISE EXCEPTION 'expr_syntax: unexpected ('; END IF;
          depth := depth + 1;
          out := out || ' (';
        ELSIF tok = ')' THEN
          IF expect_operand OR depth = 0 THEN RAISE EXCEPTION 'expr_syntax: unexpected )'; END IF;
          depth := depth - 1;
          out := out || ' )';
        ELSIF tok IN ('+', '-') THEN
          out := out || ' ' || tok;      -- binary, or unary when an operand is expected
          expect_operand := true;
        ELSIF tok IN ('*', '/') THEN
          IF expect_operand THEN RAISE EXCEPTION 'expr_syntax: unexpected %', tok; END IF;
          out := out || ' ' || tok;
          expect_operand := true;
        ELSE
          RAISE EXCEPTION 'expr_invalid_character: %', tok;
        END IF;
      END IF;
    END IF;
    rest := substr(rest, length(tok) + 1);
  END LOOP;
  IF expect_operand OR depth <> 0 THEN
    RAISE EXCEPTION 'expr_syntax: incomplete expression';
  END IF;
  RETURN '(' || out || ' )';
END $$;

-- Which identifiers each kind of formula may use.
CREATE OR REPLACE FUNCTION tycoon.vars_land_base() RETURNS TEXT[] LANGUAGE sql IMMUTABLE AS
$$ SELECT ARRAY['length_m','class_weight','density_weight','slots_total'] $$;
CREATE OR REPLACE FUNCTION tycoon.vars_tick_tax() RETURNS TEXT[] LANGUAGE sql IMMUTABLE AS
$$ SELECT ARRAY['land_value','improvement_value','length_m','class_weight','density_weight',
                'slots_used','slots_total'] $$;
CREATE OR REPLACE FUNCTION tycoon.vars_purchase_tax() RETURNS TEXT[] LANGUAGE sql IMMUTABLE AS
$$ SELECT ARRAY['land_value','improvement_value','length_m','class_weight','density_weight',
                'slots_used','slots_total','sale_price'] $$;

-- Per-parcel variables that formulas are evaluated against.
CREATE OR REPLACE FUNCTION tycoon.parcel_vars(p_world UUID, p_cfg JSONB)
RETURNS TABLE (id BIGINT, owner_id UUID, land_value NUMERIC, improvement_value NUMERIC,
               length_m NUMERIC, class_weight NUMERIC, density_weight NUMERIC,
               slots_used NUMERIC, slots_total NUMERIC, sale_price NUMERIC)
LANGUAGE sql STABLE AS $$
  SELECT p.id, p.owner_id,
         p.land_value::NUMERIC, p.improvement_value::NUMERIC, p.length_m::NUMERIC,
         (p_cfg -> 'valuation' -> 'class_weights' ->> p.highway_class)::NUMERIC,
         p.density_weight,
         COALESCE(u.used, 0)::NUMERIC, p.slots_total::NUMERIC,
         (p.land_value + p.improvement_value)::NUMERIC
  FROM tycoon.parcels p
  LEFT JOIN LATERAL (SELECT SUM(i.slots_used) AS used FROM tycoon.improvements i
                     WHERE i.parcel_id = p.id) u ON true
  WHERE p.world_id = p_world
$$;

-- Evaluate a formula for a single parcel.
CREATE OR REPLACE FUNCTION tycoon.eval_parcel_expr(p_world UUID, p_cfg JSONB, p_expr TEXT,
                                                   p_allowed TEXT[], p_parcel BIGINT)
RETURNS NUMERIC LANGUAGE plpgsql STABLE AS $$
DECLARE r NUMERIC;
BEGIN
  EXECUTE format('SELECT %s FROM tycoon.parcel_vars($1, $2) v WHERE v.id = $3',
                 tycoon.compile_expr(p_expr, p_allowed))
    INTO r USING p_world, p_cfg, p_parcel;
  RETURN r;
END $$;

-- Tax owed per parcel for one configured tax.
CREATE OR REPLACE FUNCTION tycoon.tax_rows(p_world UUID, p_cfg JSONB, p_tax JSONB, p_allowed TEXT[])
RETURNS TABLE (parcel_id BIGINT, owner_id UUID, base NUMERIC, amount BIGINT)
LANGUAGE plpgsql STABLE AS $$
DECLARE e TEXT := tycoon.compile_expr(p_tax ->> 'base', p_allowed);
BEGIN
  RETURN QUERY EXECUTE format(
    'SELECT v.id, v.owner_id, %1$s, tycoon.apply_bp(GREATEST(%1$s, 0), $3) '
    'FROM tycoon.parcel_vars($1, $2) v', e)
    USING p_world, p_cfg, (p_tax ->> 'rate_bp')::NUMERIC;
END $$;

-- Income owed per parcel.
CREATE OR REPLACE FUNCTION tycoon.income_rows(p_world UUID, p_cfg JSONB)
RETURNS TABLE (parcel_id BIGINT, owner_id UUID, income_land BIGINT, income_improvements BIGINT)
LANGUAGE sql STABLE AS $$
  SELECT p.id, p.owner_id,
         tycoon.apply_bp(p.land_value, (p_cfg -> 'income' ->> 'from_land_bp')::NUMERIC),
         COALESCE((SELECT SUM(tycoon.apply_bp(tycoon.apply_bp(i.cost, bt.yield_bp),
                                              (p_cfg -> 'income' ->> 'from_improvements_bp')::NUMERIC))
                   FROM tycoon.improvements i JOIN tycoon.building_types bt ON bt.id = i.type_id
                   WHERE i.parcel_id = p.id), 0)::BIGINT
  FROM tycoon.parcels p
  WHERE p.world_id = p_world
$$;

-- Vacancy penalty per parcel (charged on land_value when nothing is built).
CREATE OR REPLACE FUNCTION tycoon.vacancy_rows(p_world UUID, p_cfg JSONB)
RETURNS TABLE (parcel_id BIGINT, owner_id UUID, amount BIGINT)
LANGUAGE sql STABLE AS $$
  SELECT v.id, v.owner_id,
         tycoon.apply_bp(v.land_value, COALESCE((p_cfg ->> 'vacancy_penalty_bp')::NUMERIC, 0))
  FROM tycoon.parcel_vars(p_world, p_cfg) v
  WHERE v.slots_used = 0
$$;

-- Density weight for a location: grows with the number of parcels nearby.
CREATE OR REPLACE FUNCTION tycoon.density_for(p_world UUID, p_cfg JSONB, p_lat DOUBLE PRECISION,
                                              p_lon DOUBLE PRECISION, p_exclude BIGINT)
RETURNS NUMERIC LANGUAGE sql STABLE AS $$
  WITH d AS (SELECT p_cfg -> 'valuation' -> 'density' AS c)
  SELECT LEAST((d.c ->> 'max')::NUMERIC,
               (d.c ->> 'base')::NUMERIC + (d.c ->> 'per_neighbour')::NUMERIC * (
                 SELECT count(*) FROM tycoon.parcels b
                 WHERE b.world_id = p_world
                   AND b.id IS DISTINCT FROM p_exclude
                   AND b.c_lat BETWEEN p_lat - tycoon.metres_to_lat_deg((d.c ->> 'radius_m')::FLOAT8)
                                   AND p_lat + tycoon.metres_to_lat_deg((d.c ->> 'radius_m')::FLOAT8)
                   AND tycoon.geo_dist_m(p_lat, p_lon, b.c_lat, b.c_lon) <= (d.c ->> 'radius_m')::FLOAT8))
  FROM d
$$;

-- Recompute density and land value for every parcel in a world.
CREATE OR REPLACE FUNCTION tycoon.reassess_values(p_world UUID)
RETURNS VOID LANGUAGE plpgsql AS $$
DECLARE cfg JSONB := tycoon.world_config(p_world);
BEGIN
  UPDATE tycoon.parcels p
     SET density_weight = tycoon.density_for(p_world, cfg, p.c_lat, p.c_lon, p.id)
   WHERE p.world_id = p_world;
  EXECUTE format(
    'UPDATE tycoon.parcels p SET land_value = GREATEST(round(%s), 0)::BIGINT '
    'FROM tycoon.parcel_vars($1, $2) v WHERE v.id = p.id',
    tycoon.compile_expr(cfg -> 'valuation' ->> 'land_base', tycoon.vars_land_base()))
    USING p_world, cfg;
END $$;

-- ---------------------------------------------------------------------
-- The tick. Set-based SQL only; every rate comes from the ruleset.
-- ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION tycoon.run_tick(p_world UUID)
RETURNS BIGINT LANGUAGE plpgsql AS $$
DECLARE
  cfg JSONB;
  v_tick BIGINT;
  v_n INT;
  v_every INT;
  t JSONB;
BEGIN
  SELECT r.config INTO cfg
    FROM tycoon.worlds w JOIN tycoon.rulesets r ON r.id = w.ruleset_id
   WHERE w.id = p_world
     FOR UPDATE OF w;
  IF cfg IS NULL THEN RAISE EXCEPTION 'world_not_found'; END IF;

  -- 1. Record the tick with a snapshot of the ruleset.
  UPDATE tycoon.worlds SET tick_count = tick_count + 1 WHERE id = p_world
  RETURNING tick_count INTO v_n;
  INSERT INTO tycoon.ticks (world_id, tick_number, ruleset_snapshot)
  VALUES (p_world, v_n, cfg) RETURNING id INTO v_tick;

  -- 2. improvement_value = SUM(improvements.cost)
  UPDATE tycoon.parcels p SET improvement_value = s.total
    FROM (SELECT q.id, COALESCE((SELECT SUM(i.cost) FROM tycoon.improvements i
                                 WHERE i.parcel_id = q.id), 0)::BIGINT AS total
            FROM tycoon.parcels q WHERE q.world_id = p_world) s
   WHERE p.id = s.id AND p.improvement_value <> s.total;

  -- 3. Periodic reassessment.
  v_every := (cfg -> 'valuation' ->> 'reassess_every_ticks')::INT;
  IF v_every > 0 AND v_n % v_every = 0 THEN
    PERFORM tycoon.reassess_values(p_world);
  END IF;

  -- 4. Income: bank -> player, aggregated per player and per source.
  INSERT INTO tycoon.ledger (world_id, tick_id, from_account, to_account, amount, reason)
  SELECT p_world, v_tick, 'bank', tycoon.player_account(x.owner_id), x.amount, x.reason
    FROM (SELECT r.owner_id, 'income:land' AS reason, SUM(r.income_land)::BIGINT AS amount
            FROM tycoon.income_rows(p_world, cfg) r WHERE r.owner_id IS NOT NULL GROUP BY r.owner_id
          UNION ALL
          SELECT r.owner_id, 'income:improvements', SUM(r.income_improvements)::BIGINT
            FROM tycoon.income_rows(p_world, cfg) r WHERE r.owner_id IS NOT NULL GROUP BY r.owner_id) x
   WHERE x.amount > 0;

  -- 5. Taxes: player -> treasury, one INSERT ... SELECT per configured tax.
  FOR t IN SELECT value FROM jsonb_array_elements(COALESCE(cfg -> 'taxes', '[]'::JSONB))
            WHERE COALESCE(value ->> 'on', 'tick') = 'tick' LOOP
    INSERT INTO tycoon.ledger (world_id, tick_id, from_account, to_account, amount, reason)
    SELECT p_world, v_tick, tycoon.player_account(r.owner_id), 'treasury', SUM(r.amount)::BIGINT,
           'tax:' || (t ->> 'id')
      FROM tycoon.tax_rows(p_world, cfg, t, tycoon.vars_tick_tax()) r
     WHERE r.owner_id IS NOT NULL
     GROUP BY r.owner_id
    HAVING SUM(r.amount) > 0;
  END LOOP;

  INSERT INTO tycoon.ledger (world_id, tick_id, from_account, to_account, amount, reason)
  SELECT p_world, v_tick, tycoon.player_account(r.owner_id), 'treasury', SUM(r.amount)::BIGINT,
         'tax:vacancy'
    FROM tycoon.vacancy_rows(p_world, cfg) r
   WHERE r.owner_id IS NOT NULL
   GROUP BY r.owner_id
  HAVING SUM(r.amount) > 0;

  -- 6. Leasehold expiry.
  IF cfg -> 'tenure' ->> 'type' = 'leasehold' THEN
    INSERT INTO tycoon.events (world_id, player_id, kind, parcel_id)
    SELECT world_id, owner_id, 'lease_expired', id FROM tycoon.parcels
     WHERE world_id = p_world AND owner_id IS NOT NULL AND lease_expires_at < now();
    UPDATE tycoon.parcels SET owner_id = NULL, acquired_at = NULL, lease_expires_at = NULL
     WHERE world_id = p_world AND owner_id IS NOT NULL AND lease_expires_at < now();
  END IF;

  RETURN v_tick;
END $$;

-- Dispatcher: runs whichever worlds are due, based on each ruleset's own
-- cadence. Called by pg_cron every minute and lazily by player requests.
CREATE OR REPLACE FUNCTION tycoon.run_due_ticks()
RETURNS INT LANGUAGE plpgsql AS $$
DECLARE
  w RECORD;
  n INT := 0;
  k INT;
  iv INTERVAL;
  cap INT;
BEGIN
  FOR w IN SELECT wo.id, r.config FROM tycoon.worlds wo
             JOIN tycoon.rulesets r ON r.id = wo.ruleset_id
            WHERE wo.status = 'running' AND wo.next_tick_at <= now()
              FOR UPDATE OF wo SKIP LOCKED LOOP
    iv := (w.config -> 'tick' ->> 'interval')::INTERVAL;
    cap := COALESCE((w.config -> 'tick' ->> 'max_catch_up')::INT, 1);
    k := 0;
    WHILE k < cap AND (SELECT next_tick_at FROM tycoon.worlds WHERE id = w.id) <= now() LOOP
      PERFORM tycoon.run_tick(w.id);
      UPDATE tycoon.worlds SET next_tick_at = next_tick_at + iv WHERE id = w.id;
      k := k + 1;
    END LOOP;
    -- Too far behind: skip ahead rather than replaying days of ticks.
    UPDATE tycoon.worlds SET next_tick_at = now() + iv WHERE id = w.id AND next_tick_at <= now();
    n := n + k;
  END LOOP;
  RETURN n;
END $$;

-- ---------------------------------------------------------------------
-- Player actions. Every one locks the player row first (so one player
-- can't overspend with parallel requests), then the parcel row.
-- ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION tycoon.lock_player(p_player UUID)
RETURNS tycoon.players LANGUAGE plpgsql AS $$
DECLARE pl tycoon.players;
BEGIN
  SELECT * INTO pl FROM tycoon.players WHERE id = p_player FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'player_not_found'; END IF;
  RETURN pl;
END $$;

CREATE OR REPLACE FUNCTION tycoon.join_world(p_account UUID, p_world UUID)
RETURNS UUID LANGUAGE plpgsql AS $$
DECLARE
  v_id UUID;
  v_handle TEXT;
  cfg JSONB := tycoon.world_config(p_world);
BEGIN
  IF cfg IS NULL THEN RAISE EXCEPTION 'world_not_found'; END IF;
  SELECT id INTO v_id FROM tycoon.players WHERE world_id = p_world AND account_id = p_account;
  IF FOUND THEN RETURN v_id; END IF;
  SELECT username INTO v_handle FROM tycoon.accounts WHERE id = p_account;
  INSERT INTO tycoon.players (world_id, account_id, handle)
  VALUES (p_world, p_account, v_handle)
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NULL THEN
    SELECT id INTO v_id FROM tycoon.players WHERE world_id = p_world AND account_id = p_account;
    RETURN v_id;
  END IF;
  -- Starting capital is a repayable loan recorded in the ledger, not a grant.
  IF (cfg ->> 'starting_loan')::BIGINT > 0 THEN
    INSERT INTO tycoon.ledger (world_id, from_account, to_account, amount, reason)
    VALUES (p_world, 'bank', tycoon.player_account(v_id), (cfg ->> 'starting_loan')::BIGINT, 'loan');
  END IF;
  INSERT INTO tycoon.events (world_id, player_id, kind) VALUES (p_world, v_id, 'joined');
  RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION tycoon.purchase_parcel(p_player UUID, p_parcel BIGINT)
RETURNS BIGINT LANGUAGE plpgsql AS $$
DECLARE
  pl tycoon.players := tycoon.lock_player(p_player);
  p tycoon.parcels;
  cfg JSONB;
  price BIGINT;
  t JSONB;
  taxes JSONB := '[]'::JSONB;
  total_tax BIGINT := 0;
  amt BIGINT;
  acct TEXT := tycoon.player_account(p_player);
BEGIN
  SELECT * INTO p FROM tycoon.parcels WHERE id = p_parcel FOR UPDATE;   -- lock first
  IF NOT FOUND THEN RAISE EXCEPTION 'parcel_not_found'; END IF;
  IF p.world_id <> pl.world_id THEN RAISE EXCEPTION 'wrong_world'; END IF;
  IF p.owner_id IS NOT NULL THEN RAISE EXCEPTION 'parcel_already_owned'; END IF;
  cfg := tycoon.world_config(p.world_id);
  price := p.land_value + p.improvement_value;

  FOR t IN SELECT value FROM jsonb_array_elements(COALESCE(cfg -> 'taxes', '[]'::JSONB))
            WHERE value ->> 'on' = 'purchase' LOOP
    amt := tycoon.apply_bp(GREATEST(tycoon.eval_parcel_expr(p.world_id, cfg, t ->> 'base',
                                    tycoon.vars_purchase_tax(), p.id), 0),
                           (t ->> 'rate_bp')::NUMERIC);
    taxes := taxes || jsonb_build_object('id', t ->> 'id', 'amount', amt);
    total_tax := total_tax + amt;
  END LOOP;

  IF tycoon.balance_of(p.world_id, acct) < price + total_tax THEN
    RAISE EXCEPTION 'insufficient_funds';
  END IF;

  IF price > 0 THEN
    INSERT INTO tycoon.ledger (world_id, from_account, to_account, amount, reason, parcel_id)
    VALUES (p.world_id, acct, 'bank', price, 'purchase', p.id);
  END IF;
  INSERT INTO tycoon.ledger (world_id, from_account, to_account, amount, reason, parcel_id)
  SELECT p.world_id, acct, 'treasury', (x ->> 'amount')::BIGINT, 'tax:' || (x ->> 'id'), p.id
    FROM jsonb_array_elements(taxes) x WHERE (x ->> 'amount')::BIGINT > 0;

  UPDATE tycoon.parcels
     SET owner_id = p_player, acquired_at = now(),
         lease_expires_at = CASE WHEN cfg -> 'tenure' ->> 'type' = 'leasehold'
           THEN now() + ((cfg ->> 'lease_term_ticks')::INT * (cfg -> 'tick' ->> 'interval')::INTERVAL)
           END
   WHERE id = p.id;

  INSERT INTO tycoon.events (world_id, player_id, kind, parcel_id, data)
  VALUES (p.world_id, p_player, 'purchase', p.id, jsonb_build_object('price', price));
  RETURN tycoon.balance_of(p.world_id, acct);
END $$;

-- p_slot: the plot to build on (optional). Without one, the free run of
-- plots closest to the middle of the street is used.
DROP FUNCTION IF EXISTS tycoon.build_improvement(UUID, BIGINT, TEXT);
CREATE OR REPLACE FUNCTION tycoon.build_improvement(p_player UUID, p_parcel BIGINT, p_type TEXT,
                                                    p_slot INT DEFAULT NULL)
RETURNS BIGINT LANGUAGE plpgsql AS $$
DECLARE
  pl tycoon.players := tycoon.lock_player(p_player);
  p tycoon.parcels;
  bt tycoon.building_types;
  v_slot INT;
  acct TEXT := tycoon.player_account(p_player);
BEGIN
  SELECT * INTO p FROM tycoon.parcels WHERE id = p_parcel FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'parcel_not_found'; END IF;
  IF p.world_id <> pl.world_id THEN RAISE EXCEPTION 'wrong_world'; END IF;
  IF p.owner_id IS DISTINCT FROM p_player THEN RAISE EXCEPTION 'not_owner'; END IF;
  SELECT * INTO bt FROM tycoon.building_types WHERE id = p_type;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_building_type'; END IF;

  -- A run of free consecutive plots big enough for this building: the one
  -- requested, or else the one nearest the middle of the street.
  SELECT s INTO v_slot
    FROM generate_series(0, p.slots_total - bt.slots_used) s
   WHERE NOT EXISTS (SELECT 1 FROM tycoon.improvements i
                      WHERE i.parcel_id = p.id
                        AND i.slot_index < s + bt.slots_used
                        AND s < i.slot_index + i.slots_used)
     AND (p_slot IS NULL OR p_slot BETWEEN s AND s + bt.slots_used - 1)
   ORDER BY CASE WHEN p_slot IS NULL THEN abs(2 * s + bt.slots_used - p.slots_total) ELSE abs(s - p_slot) END, s
   LIMIT 1;
  IF v_slot IS NULL THEN
    RAISE EXCEPTION '%', CASE WHEN p_slot IS NULL THEN 'no_free_slots' ELSE 'plot_taken' END;
  END IF;

  IF tycoon.balance_of(p.world_id, acct) < bt.cost THEN
    RAISE EXCEPTION 'insufficient_funds';
  END IF;

  INSERT INTO tycoon.ledger (world_id, from_account, to_account, amount, reason, parcel_id)
  VALUES (p.world_id, acct, 'bank', bt.cost, 'build', p.id);
  INSERT INTO tycoon.improvements (parcel_id, type_id, cost, slots_used, slot_index)
  VALUES (p.id, bt.id, bt.cost, bt.slots_used, v_slot);
  UPDATE tycoon.parcels SET improvement_value = improvement_value + bt.cost WHERE id = p.id;

  INSERT INTO tycoon.events (world_id, player_id, kind, parcel_id, data)
  VALUES (p.world_id, p_player, 'build', p.id, jsonb_build_object('type_id', bt.id));
  RETURN tycoon.balance_of(p.world_id, acct);
END $$;

CREATE OR REPLACE FUNCTION tycoon.demolish_improvement(p_player UUID, p_improvement BIGINT)
RETURNS BIGINT LANGUAGE plpgsql AS $$
DECLARE
  pl tycoon.players := tycoon.lock_player(p_player);
  imp tycoon.improvements;
  p tycoon.parcels;
BEGIN
  SELECT * INTO imp FROM tycoon.improvements WHERE id = p_improvement;
  IF NOT FOUND THEN RAISE EXCEPTION 'improvement_not_found'; END IF;
  SELECT * INTO p FROM tycoon.parcels WHERE id = imp.parcel_id FOR UPDATE;
  IF p.world_id <> pl.world_id THEN RAISE EXCEPTION 'wrong_world'; END IF;
  IF p.owner_id IS DISTINCT FROM p_player THEN RAISE EXCEPTION 'not_owner'; END IF;
  DELETE FROM tycoon.improvements WHERE id = imp.id;
  UPDATE tycoon.parcels SET improvement_value = GREATEST(improvement_value - imp.cost, 0) WHERE id = p.id;
  INSERT INTO tycoon.events (world_id, player_id, kind, parcel_id, data)
  VALUES (p.world_id, p_player, 'demolish', p.id, jsonb_build_object('type_id', imp.type_id));
  RETURN tycoon.balance_of(p.world_id, tycoon.player_account(p_player));
END $$;

-- Hand a street back to the bank. No money changes hands: the only ways
-- money ever reaches a player are the starting loan and tick income.
CREATE OR REPLACE FUNCTION tycoon.release_parcel(p_player UUID, p_parcel BIGINT)
RETURNS BIGINT LANGUAGE plpgsql AS $$
DECLARE
  pl tycoon.players := tycoon.lock_player(p_player);
  p tycoon.parcels;
BEGIN
  SELECT * INTO p FROM tycoon.parcels WHERE id = p_parcel FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'parcel_not_found'; END IF;
  IF p.world_id <> pl.world_id THEN RAISE EXCEPTION 'wrong_world'; END IF;
  IF p.owner_id IS DISTINCT FROM p_player THEN RAISE EXCEPTION 'not_owner'; END IF;
  UPDATE tycoon.parcels SET owner_id = NULL, acquired_at = NULL, lease_expires_at = NULL
   WHERE id = p.id;
  INSERT INTO tycoon.events (world_id, player_id, kind, parcel_id)
  VALUES (p.world_id, p_player, 'release', p.id);
  RETURN tycoon.balance_of(p.world_id, tycoon.player_account(p_player));
END $$;

CREATE OR REPLACE FUNCTION tycoon.repay_loan(p_player UUID, p_amount BIGINT)
RETURNS BIGINT LANGUAGE plpgsql AS $$
DECLARE
  pl tycoon.players := tycoon.lock_player(p_player);
  acct TEXT := tycoon.player_account(p_player);
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN RAISE EXCEPTION 'invalid_amount'; END IF;
  IF p_amount > tycoon.loan_outstanding(pl.world_id, p_player) THEN
    RAISE EXCEPTION 'amount_exceeds_loan';
  END IF;
  IF p_amount > tycoon.balance_of(pl.world_id, acct) THEN RAISE EXCEPTION 'insufficient_funds'; END IF;
  INSERT INTO tycoon.ledger (world_id, from_account, to_account, amount, reason)
  VALUES (pl.world_id, acct, 'bank', p_amount, 'loan_repayment');
  RETURN tycoon.balance_of(pl.world_id, acct);
END $$;

-- ---------------------------------------------------------------------
-- Street claiming. The browser looks a street up in OpenStreetMap and
-- submits its ways; the server validates them, computes length, class,
-- slots and land value itself, and creates the parcel. A way can belong
-- to only one parcel per world, so the same street always resolves to the
-- same parcel no matter where on it you click.
-- p_ways: [{"id": 123, "highway": "residential", "coords": [[lon,lat], ...]}, ...]
-- ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION tycoon.claim_parcel(p_world UUID, p_name TEXT, p_suburb TEXT,
                                               p_anchor BIGINT, p_ways JSONB)
RETURNS BIGINT LANGUAGE plpgsql AS $$
DECLARE
  cfg JSONB := tycoon.world_config(p_world);
  v_id BIGINT;
  v_ids BIGINT[];
  v_geom JSONB;
  v_len DOUBLE PRECISION;
  v_class TEXT;
  c RECORD;
  v_slots INT;
  v_land NUMERIC;
BEGIN
  IF cfg IS NULL THEN RAISE EXCEPTION 'world_not_found'; END IF;
  p_name := btrim(p_name);
  IF p_name IS NULL OR p_name = '' OR length(p_name) > 200 THEN RAISE EXCEPTION 'invalid_name'; END IF;
  IF p_suburb IS NOT NULL AND length(p_suburb) > 200 THEN p_suburb := left(p_suburb, 200); END IF;
  IF jsonb_typeof(p_ways) <> 'array' OR jsonb_array_length(p_ways) = 0
     OR jsonb_array_length(p_ways) > 500 THEN
    RAISE EXCEPTION 'invalid_geometry';
  END IF;

  -- Serialise claims within a world so a way is never claimed twice.
  PERFORM pg_advisory_xact_lock(hashtext('tycoon-claim'), hashtext(p_world::TEXT));

  SELECT id INTO v_id FROM tycoon.parcels
   WHERE world_id = p_world AND osm_way_ids @> ARRAY[p_anchor] LIMIT 1;
  IF FOUND THEN RETURN v_id; END IF;

  CREATE TEMP TABLE IF NOT EXISTS _claim_pts (way_id BIGINT, hw TEXT, ord INT, lon FLOAT8, lat FLOAT8)
    ON COMMIT DROP;
  TRUNCATE _claim_pts;
  INSERT INTO _claim_pts
  SELECT (w ->> 'id')::BIGINT, w ->> 'highway', pt.ord::INT, (pt.v ->> 0)::FLOAT8, (pt.v ->> 1)::FLOAT8
    FROM jsonb_array_elements(p_ways) w
    CROSS JOIN LATERAL jsonb_array_elements(w -> 'coords') WITH ORDINALITY AS pt(v, ord)
   WHERE jsonb_typeof(w -> 'coords') = 'array'
     AND (cfg -> 'valuation' -> 'class_weights') ? (w ->> 'highway')
     AND NOT EXISTS (SELECT 1 FROM tycoon.parcels q
                      WHERE q.world_id = p_world AND q.osm_way_ids @> ARRAY[(w ->> 'id')::BIGINT]);

  IF EXISTS (SELECT 1 FROM _claim_pts WHERE lon IS NULL OR lat IS NULL
               OR lon NOT BETWEEN -180 AND 180 OR lat NOT BETWEEN -85 AND 85) THEN
    RAISE EXCEPTION 'invalid_geometry';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM _claim_pts WHERE way_id = p_anchor) THEN
    RAISE EXCEPTION 'street_not_claimable';
  END IF;
  IF (SELECT count(*) FROM _claim_pts) > 20000 THEN RAISE EXCEPTION 'invalid_geometry'; END IF;

  -- Per-way length, then totals.
  CREATE TEMP TABLE IF NOT EXISTS _claim_ways (way_id BIGINT, hw TEXT, len FLOAT8, pts INT)
    ON COMMIT DROP;
  TRUNCATE _claim_ways;
  INSERT INTO _claim_ways
  SELECT way_id, min(hw), COALESCE(SUM(seg), 0), count(*)
    FROM (SELECT way_id, hw,
                 tycoon.geo_dist_m(lag(lat) OVER w, lag(lon) OVER w, lat, lon) AS seg
            FROM _claim_pts WINDOW w AS (PARTITION BY way_id ORDER BY ord)) s
   GROUP BY way_id;
  DELETE FROM _claim_ways WHERE pts < 2;
  IF NOT EXISTS (SELECT 1 FROM _claim_ways WHERE way_id = p_anchor) THEN
    RAISE EXCEPTION 'invalid_geometry';
  END IF;

  SELECT SUM(len), array_agg(way_id ORDER BY way_id) INTO v_len, v_ids FROM _claim_ways;
  IF v_len IS NULL OR v_len <= 0 THEN RAISE EXCEPTION 'invalid_geometry'; END IF;
  IF v_len > 50000 THEN RAISE EXCEPTION 'street_too_long'; END IF;

  -- Class = the highway type covering the most length.
  SELECT hw INTO v_class FROM _claim_ways GROUP BY hw ORDER BY SUM(len) DESC, hw LIMIT 1;

  SELECT jsonb_agg(line ORDER BY way_id) INTO v_geom FROM (
    SELECT p.way_id, jsonb_agg(jsonb_build_array(p.lon, p.lat) ORDER BY p.ord) AS line
      FROM _claim_pts p JOIN _claim_ways w ON w.way_id = p.way_id
     GROUP BY p.way_id) l;

  SELECT avg(p.lon) AS c_lon, avg(p.lat) AS c_lat, min(p.lon) AS min_lon, min(p.lat) AS min_lat,
         max(p.lon) AS max_lon, max(p.lat) AS max_lat
    INTO c
    FROM _claim_pts p JOIN _claim_ways w ON w.way_id = p.way_id;

  v_slots := LEAST((cfg -> 'slots' ->> 'max')::INT,
                   GREATEST((cfg -> 'slots' ->> 'min')::INT,
                            floor(v_len / (cfg -> 'slots' ->> 'metres_per_slot')::FLOAT8)::INT));

  INSERT INTO tycoon.parcels (world_id, name, suburb, osm_way_ids, geom, c_lon, c_lat,
                              min_lon, min_lat, max_lon, max_lat, length_m, highway_class,
                              slots_total, density_weight, land_value)
  VALUES (p_world, p_name, NULLIF(btrim(p_suburb), ''), v_ids, v_geom, c.c_lon, c.c_lat,
          c.min_lon, c.min_lat, c.max_lon, c.max_lat, v_len, v_class, v_slots,
          tycoon.density_for(p_world, cfg, c.c_lat, c.c_lon, NULL), 0)
  RETURNING id INTO v_id;

  v_land := tycoon.eval_parcel_expr(p_world, cfg, cfg -> 'valuation' ->> 'land_base',
                                    tycoon.vars_land_base(), v_id);
  UPDATE tycoon.parcels SET land_value = GREATEST(round(v_land), 0)::BIGINT WHERE id = v_id;
  RETURN v_id;
END $$;

-- >>> 003_api.sql
-- =====================================================================
-- Tycoon: public API.
-- Every function here takes one JSON argument `p` and returns JSON, so the
-- browser can call them identically over Supabase's REST endpoint
-- (POST /rest/v1/rpc/tycoon_xxx {"p": {...}}) or against an in-browser
-- PGlite database (SELECT public.tycoon_xxx($1)).
-- All are SECURITY DEFINER: they authenticate the caller from a session
-- token and then call the internal functions in schema `tycoon`.
-- =====================================================================

-- Best-effort client IP from the HTTP headers PostgREST exposes.
CREATE OR REPLACE FUNCTION tycoon.request_ip()
RETURNS TEXT LANGUAGE plpgsql STABLE AS $$
DECLARE h JSON;
BEGIN
  h := NULLIF(current_setting('request.headers', true), '')::JSON;
  IF h IS NULL THEN RETURN NULL; END IF;
  RETURN COALESCE(NULLIF(btrim(split_part(h ->> 'x-forwarded-for', ',', 1)), ''),
                  h ->> 'cf-connecting-ip', h ->> 'x-real-ip');
EXCEPTION WHEN others THEN
  RETURN NULL;
END $$;

CREATE OR REPLACE FUNCTION tycoon.new_session(p_account UUID, p_ip TEXT)
RETURNS JSONB LANGUAGE plpgsql AS $$
DECLARE v_token TEXT := encode(extensions.gen_random_bytes(24), 'hex');
BEGIN
  INSERT INTO tycoon.sessions (token, account_id, ip) VALUES (v_token, p_account, p_ip);
  RETURN jsonb_build_object('token', v_token, 'account',
    (SELECT jsonb_build_object('id', a.id, 'username', a.username) FROM tycoon.accounts a
      WHERE a.id = p_account));
END $$;

CREATE OR REPLACE FUNCTION tycoon.auth_account(p JSONB)
RETURNS UUID LANGUAGE plpgsql AS $$
DECLARE v UUID;
BEGIN
  UPDATE tycoon.sessions SET last_seen_at = now()
   WHERE token = p ->> 'token' AND last_seen_at > now() - INTERVAL '30 days'
  RETURNING account_id INTO v;
  IF v IS NULL THEN RAISE EXCEPTION 'not_logged_in'; END IF;
  RETURN v;
END $$;

CREATE OR REPLACE FUNCTION tycoon.auth_player(p JSONB)
RETURNS UUID LANGUAGE plpgsql AS $$
DECLARE v UUID; a UUID := tycoon.auth_account(p);
BEGIN
  UPDATE tycoon.players SET last_seen_at = now()
   WHERE account_id = a AND world_id = (p ->> 'world_id')::UUID
  RETURNING id INTO v;
  IF v IS NULL THEN RAISE EXCEPTION 'not_joined'; END IF;
  RETURN v;
END $$;

-- Everything the side panel needs about one street, including what it
-- would earn and pay per tick under this world's ruleset.
CREATE OR REPLACE FUNCTION tycoon.parcel_json(p_id BIGINT, p_detail BOOLEAN)
RETURNS JSONB LANGUAGE plpgsql STABLE AS $$
DECLARE
  p tycoon.parcels;
  cfg JSONB;
  j JSONB;
  inc RECORD;
  t JSONB;
  taxes JSONB := '[]'::JSONB;
  ptaxes JSONB := '[]'::JSONB;
  amt BIGINT;
  base NUMERIC;
  vac BIGINT;
BEGIN
  SELECT * INTO p FROM tycoon.parcels WHERE id = p_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  j := jsonb_build_object(
    'id', p.id, 'name', p.name, 'suburb', p.suburb, 'highway_class', p.highway_class,
    'length_m', round(p.length_m::NUMERIC, 1), 'slots_total', p.slots_total,
    'slots_used', COALESCE((SELECT SUM(slots_used) FROM tycoon.improvements WHERE parcel_id = p.id), 0),
    'land_value', p.land_value, 'improvement_value', p.improvement_value,
    'price', p.land_value + p.improvement_value,
    'owner_id', p.owner_id,
    'owner_handle', (SELECT handle FROM tycoon.players WHERE id = p.owner_id),
    'acquired_at', p.acquired_at, 'lease_expires_at', p.lease_expires_at,
    'c_lon', p.c_lon, 'c_lat', p.c_lat, 'geom', p.geom,
    'improvements', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'id', i.id, 'type_id', i.type_id, 'slot_index', i.slot_index,
        'slots_used', i.slots_used, 'cost', i.cost, 'built_at', i.built_at) ORDER BY i.slot_index)
      FROM tycoon.improvements i WHERE i.parcel_id = p.id), '[]'::JSONB));
  IF NOT p_detail THEN RETURN j; END IF;

  cfg := tycoon.world_config(p.world_id);
  SELECT * INTO inc FROM tycoon.income_rows(p.world_id, cfg) r WHERE r.parcel_id = p.id;
  FOR t IN SELECT value FROM jsonb_array_elements(COALESCE(cfg -> 'taxes', '[]'::JSONB)) LOOP
    IF t ->> 'on' = 'purchase' THEN
      base := tycoon.eval_parcel_expr(p.world_id, cfg, t ->> 'base', tycoon.vars_purchase_tax(), p.id);
      amt := tycoon.apply_bp(GREATEST(base, 0), (t ->> 'rate_bp')::NUMERIC);
      ptaxes := ptaxes || jsonb_build_object('id', t ->> 'id', 'base_expr', t ->> 'base',
                  'base', round(base), 'rate_bp', (t ->> 'rate_bp')::INT, 'amount', amt);
    ELSE
      SELECT r.base, r.amount INTO base, amt
        FROM tycoon.tax_rows(p.world_id, cfg, t, tycoon.vars_tick_tax()) r WHERE r.parcel_id = p.id;
      taxes := taxes || jsonb_build_object('id', t ->> 'id', 'base_expr', t ->> 'base',
                 'base', round(base), 'rate_bp', (t ->> 'rate_bp')::INT, 'amount', amt);
    END IF;
  END LOOP;
  SELECT r.amount INTO vac FROM tycoon.vacancy_rows(p.world_id, cfg) r WHERE r.parcel_id = p.id;
  IF COALESCE(vac, 0) > 0 THEN
    taxes := taxes || jsonb_build_object('id', 'vacancy', 'base_expr', 'land_value (when nothing is built)',
               'base', p.land_value, 'rate_bp', (cfg ->> 'vacancy_penalty_bp')::INT, 'amount', vac);
  END IF;
  RETURN j || jsonb_build_object(
    'per_tick', jsonb_build_object(
      'income_land', inc.income_land,
      'income_improvements', inc.income_improvements,
      'taxes', taxes,
      'net', inc.income_land + inc.income_improvements
             - COALESCE((SELECT SUM((x ->> 'amount')::BIGINT) FROM jsonb_array_elements(taxes) x), 0)),
    'purchase', jsonb_build_object(
      'price', p.land_value + p.improvement_value,
      'taxes', ptaxes,
      'total', p.land_value + p.improvement_value
               + COALESCE((SELECT SUM((x ->> 'amount')::BIGINT) FROM jsonb_array_elements(ptaxes) x), 0)));
END $$;

CREATE OR REPLACE FUNCTION tycoon.player_summary(p_player UUID)
RETURNS JSONB LANGUAGE plpgsql STABLE AS $$
DECLARE
  pl tycoon.players;
  acct TEXT := tycoon.player_account(p_player);
  bal BIGINT;
  loan BIGINT;
  agg RECORD;
  lt RECORD;
  cfg JSONB;
  w tycoon.worlds;
BEGIN
  SELECT * INTO pl FROM tycoon.players WHERE id = p_player;
  SELECT * INTO w FROM tycoon.worlds WHERE id = pl.world_id;
  cfg := tycoon.world_config(pl.world_id);
  bal := tycoon.balance_of(pl.world_id, acct);
  loan := tycoon.loan_outstanding(pl.world_id, p_player);
  SELECT count(*) AS n, COALESCE(SUM(land_value), 0) AS land, COALESCE(SUM(improvement_value), 0) AS impr
    INTO agg FROM tycoon.parcels WHERE world_id = pl.world_id AND owner_id = p_player;
  SELECT id, tick_number, ran_at INTO lt FROM tycoon.ticks
   WHERE world_id = pl.world_id ORDER BY id DESC LIMIT 1;
  RETURN jsonb_build_object(
    'player', jsonb_build_object('id', pl.id, 'handle', pl.handle, 'world_id', pl.world_id),
    'world', jsonb_build_object('id', w.id, 'name', w.name, 'ruleset_id', w.ruleset_id,
                                'tick_count', w.tick_count, 'next_tick_at', w.next_tick_at,
                                'tick_interval', cfg -> 'tick' ->> 'interval'),
    'currency', cfg -> 'currency',
    'balance', bal,
    'loan_outstanding', loan,
    'parcel_count', agg.n,
    'land_value', agg.land,
    'improvement_value', agg.impr,
    'net_worth', bal + agg.land + agg.impr - loan,
    'last_tick', CASE WHEN lt.id IS NULL THEN NULL ELSE jsonb_build_object(
      'tick_number', lt.tick_number, 'ran_at', lt.ran_at,
      'income', COALESCE((SELECT jsonb_agg(jsonb_build_object('reason', reason, 'amount', amt))
                            FROM (SELECT reason, SUM(amount) AS amt FROM tycoon.ledger
                                   WHERE tick_id = lt.id AND to_account = acct GROUP BY reason) x), '[]'::JSONB),
      'taxes', COALESCE((SELECT jsonb_agg(jsonb_build_object('reason', reason, 'amount', amt,
                                 'base_expr', (SELECT t ->> 'base' FROM jsonb_array_elements(cfg -> 'taxes') t
                                                WHERE 'tax:' || (t ->> 'id') = x.reason)))
                           FROM (SELECT reason, SUM(amount) AS amt FROM tycoon.ledger
                                  WHERE tick_id = lt.id AND from_account = acct GROUP BY reason) x), '[]'::JSONB))
    END);
END $$;

-- ------------------------------- auth --------------------------------

CREATE OR REPLACE FUNCTION public.tycoon_register(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
DECLARE
  v_user TEXT := btrim(p ->> 'username');
  v_pw TEXT := p ->> 'password';
  v_ip TEXT := tycoon.request_ip();
  v_id UUID;
BEGIN
  IF v_user IS NULL OR v_user !~ '^[A-Za-z0-9_.-]{3,20}$' THEN RAISE EXCEPTION 'invalid_username'; END IF;
  IF v_pw IS NULL OR length(v_pw) < 4 OR length(v_pw) > 200 THEN RAISE EXCEPTION 'invalid_password'; END IF;
  IF v_ip IS NOT NULL AND (SELECT count(*) FROM tycoon.accounts
                            WHERE created_ip = v_ip AND created_at > now() - INTERVAL '1 hour') >= 10 THEN
    RAISE EXCEPTION 'too_many_accounts';
  END IF;
  IF EXISTS (SELECT 1 FROM tycoon.accounts WHERE lower(username) = lower(v_user)) THEN
    RAISE EXCEPTION 'username_taken';
  END IF;
  INSERT INTO tycoon.accounts (username, password_hash, created_ip, last_ip, last_login_at)
  VALUES (v_user, extensions.crypt(v_pw, extensions.gen_salt('bf', 8)), v_ip, v_ip, now())
  RETURNING id INTO v_id;
  RETURN tycoon.new_session(v_id, v_ip);
EXCEPTION WHEN unique_violation THEN
  RAISE EXCEPTION 'username_taken';
END $$;

CREATE OR REPLACE FUNCTION public.tycoon_login(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
DECLARE
  a tycoon.accounts;
  v_ip TEXT := tycoon.request_ip();
BEGIN
  SELECT * INTO a FROM tycoon.accounts WHERE lower(username) = lower(btrim(p ->> 'username'));
  IF NOT FOUND OR a.password_hash <> extensions.crypt(COALESCE(p ->> 'password', ''), a.password_hash) THEN
    RAISE EXCEPTION 'invalid_login';
  END IF;
  UPDATE tycoon.accounts SET last_ip = COALESCE(v_ip, last_ip), last_login_at = now() WHERE id = a.id;
  RETURN tycoon.new_session(a.id, v_ip);
END $$;

CREATE OR REPLACE FUNCTION public.tycoon_session(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
DECLARE a UUID := tycoon.auth_account(p);
BEGIN
  RETURN jsonb_build_object('token', p ->> 'token', 'account',
    (SELECT jsonb_build_object('id', id, 'username', username) FROM tycoon.accounts WHERE id = a));
END $$;

CREATE OR REPLACE FUNCTION public.tycoon_logout(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
BEGIN
  DELETE FROM tycoon.sessions WHERE token = p ->> 'token';
  RETURN jsonb_build_object('ok', true);
END $$;

-- ------------------------------ worlds -------------------------------

CREATE OR REPLACE FUNCTION public.tycoon_worlds(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
BEGIN
  RETURN COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'id', w.id, 'slug', w.slug, 'name', w.name, 'status', w.status,
      'ruleset_id', r.id, 'ruleset_name', r.name, 'ruleset_description', r.description,
      'tick_interval', r.config -> 'tick' ->> 'interval', 'next_tick_at', w.next_tick_at,
      'tick_count', w.tick_count,
      'player_count', (SELECT count(*) FROM tycoon.players pl WHERE pl.world_id = w.id),
      'owned_count', (SELECT count(*) FROM tycoon.parcels pa WHERE pa.world_id = w.id AND pa.owner_id IS NOT NULL))
      ORDER BY w.slug)
    FROM tycoon.worlds w JOIN tycoon.rulesets r ON r.id = w.ruleset_id), '[]'::JSONB);
END $$;

CREATE OR REPLACE FUNCTION public.tycoon_ruleset(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
BEGIN
  RETURN (SELECT jsonb_build_object('id', r.id, 'name', r.name, 'description', r.description,
                                    'config', r.config)
            FROM tycoon.worlds w JOIN tycoon.rulesets r ON r.id = w.ruleset_id
           WHERE w.id = (p ->> 'world_id')::UUID);
END $$;

CREATE OR REPLACE FUNCTION public.tycoon_building_types(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
BEGIN
  RETURN COALESCE((SELECT jsonb_agg(to_jsonb(b) ORDER BY b.sort_order, b.cost)
                     FROM tycoon.building_types b), '[]'::JSONB);
END $$;

CREATE OR REPLACE FUNCTION public.tycoon_join(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
DECLARE v UUID;
BEGIN
  v := tycoon.join_world(tycoon.auth_account(p), (p ->> 'world_id')::UUID);
  RETURN tycoon.player_summary(v);
END $$;

-- Player status. Also runs any ticks that are due, so the game advances
-- even on a database without pg_cron.
CREATE OR REPLACE FUNCTION public.tycoon_me(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
DECLARE v UUID;
BEGIN
  PERFORM tycoon.run_due_ticks();
  v := tycoon.auth_player(p);
  RETURN tycoon.player_summary(v);
END $$;

-- ------------------------------ parcels ------------------------------

CREATE OR REPLACE FUNCTION public.tycoon_parcels_bbox(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
DECLARE
  v_world UUID := (p ->> 'world_id')::UUID;
  v_limit INT := LEAST(COALESCE((p ->> 'limit')::INT, 600), 1500);
BEGIN
  RETURN COALESCE((SELECT jsonb_agg(tycoon.parcel_json(x.id, false)) FROM (
      SELECT pa.id FROM tycoon.parcels pa
       WHERE pa.world_id = v_world
         AND box(point(pa.min_lon, pa.min_lat), point(pa.max_lon, pa.max_lat))
             && box(point((p ->> 'west')::FLOAT8, (p ->> 'south')::FLOAT8),
                    point((p ->> 'east')::FLOAT8, (p ->> 'north')::FLOAT8))
       ORDER BY (pa.owner_id IS NULL), pa.length_m DESC
       LIMIT v_limit) x), '[]'::JSONB);
END $$;

-- Lightweight dots for every owned street, for the zoomed-out world view.
CREATE OR REPLACE FUNCTION public.tycoon_owned_points(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
BEGIN
  RETURN COALESCE((SELECT jsonb_agg(jsonb_build_array(pa.id, round(pa.c_lon::NUMERIC, 5),
                                                      round(pa.c_lat::NUMERIC, 5), pa.owner_id))
                     FROM (SELECT * FROM tycoon.parcels
                            WHERE world_id = (p ->> 'world_id')::UUID AND owner_id IS NOT NULL
                            ORDER BY land_value + improvement_value DESC LIMIT 5000) pa), '[]'::JSONB);
END $$;

CREATE OR REPLACE FUNCTION public.tycoon_parcel(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
DECLARE v_id BIGINT := (p ->> 'parcel_id')::BIGINT;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM tycoon.parcels WHERE id = v_id AND world_id = (p ->> 'world_id')::UUID) THEN
    RAISE EXCEPTION 'parcel_not_found';
  END IF;
  RETURN tycoon.parcel_json(v_id, true);
END $$;

CREATE OR REPLACE FUNCTION public.tycoon_search(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
DECLARE q TEXT := '%' || replace(replace(replace(btrim(COALESCE(p ->> 'q', '')), '\', '\\'), '%', '\%'), '_', '\_') || '%';
BEGIN
  IF length(btrim(COALESCE(p ->> 'q', ''))) < 2 THEN RETURN '[]'::JSONB; END IF;
  RETURN COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'id', x.id, 'name', x.name, 'suburb', x.suburb, 'c_lon', x.c_lon, 'c_lat', x.c_lat,
      'owner_handle', (SELECT handle FROM tycoon.players WHERE id = x.owner_id),
      'price', x.land_value + x.improvement_value)) FROM (
      SELECT * FROM tycoon.parcels
       WHERE world_id = (p ->> 'world_id')::UUID
         AND (name || ' ' || COALESCE(suburb, '')) ILIKE q
       ORDER BY (owner_id IS NULL), length_m DESC LIMIT 20) x), '[]'::JSONB);
END $$;

CREATE OR REPLACE FUNCTION public.tycoon_claim(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
DECLARE v_id BIGINT;
BEGIN
  PERFORM tycoon.auth_account(p);
  v_id := tycoon.claim_parcel((p ->> 'world_id')::UUID, p ->> 'name', p ->> 'suburb',
                              (p ->> 'anchor_way')::BIGINT, p -> 'ways');
  RETURN tycoon.parcel_json(v_id, true);
END $$;

-- ------------------------------ actions ------------------------------
-- Every mutating call returns the new balance so the client never
-- computes money itself.

CREATE OR REPLACE FUNCTION public.tycoon_buy(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
DECLARE v_pl UUID := tycoon.auth_player(p); v_bal BIGINT;
BEGIN
  v_bal := tycoon.purchase_parcel(v_pl, (p ->> 'parcel_id')::BIGINT);
  RETURN jsonb_build_object('balance', v_bal, 'parcel', tycoon.parcel_json((p ->> 'parcel_id')::BIGINT, true));
END $$;

CREATE OR REPLACE FUNCTION public.tycoon_build(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
DECLARE v_pl UUID := tycoon.auth_player(p); v_bal BIGINT;
BEGIN
  v_bal := tycoon.build_improvement(v_pl, (p ->> 'parcel_id')::BIGINT, p ->> 'type_id', (p ->> 'slot')::INT);
  RETURN jsonb_build_object('balance', v_bal, 'parcel', tycoon.parcel_json((p ->> 'parcel_id')::BIGINT, true));
END $$;

CREATE OR REPLACE FUNCTION public.tycoon_demolish(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
DECLARE v_pl UUID := tycoon.auth_player(p); v_bal BIGINT; v_parcel BIGINT;
BEGIN
  SELECT parcel_id INTO v_parcel FROM tycoon.improvements WHERE id = (p ->> 'improvement_id')::BIGINT;
  v_bal := tycoon.demolish_improvement(v_pl, (p ->> 'improvement_id')::BIGINT);
  RETURN jsonb_build_object('balance', v_bal, 'parcel', tycoon.parcel_json(v_parcel, true));
END $$;

CREATE OR REPLACE FUNCTION public.tycoon_release(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
DECLARE v_pl UUID := tycoon.auth_player(p); v_bal BIGINT;
BEGIN
  v_bal := tycoon.release_parcel(v_pl, (p ->> 'parcel_id')::BIGINT);
  RETURN jsonb_build_object('balance', v_bal, 'parcel', tycoon.parcel_json((p ->> 'parcel_id')::BIGINT, true));
END $$;

CREATE OR REPLACE FUNCTION public.tycoon_repay(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
DECLARE v_pl UUID := tycoon.auth_player(p); v_bal BIGINT;
BEGIN
  v_bal := tycoon.repay_loan(v_pl, (p ->> 'amount')::BIGINT);
  RETURN jsonb_build_object('balance', v_bal);
END $$;

-- ---------------------------- read models ----------------------------

CREATE OR REPLACE FUNCTION public.tycoon_ledger(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
DECLARE
  v_pl UUID := tycoon.auth_player(p);
  acct TEXT := tycoon.player_account(v_pl);
  v_world UUID := (p ->> 'world_id')::UUID;
BEGIN
  RETURN COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'id', l.id, 'created_at', l.created_at, 'reason', l.reason,
      'amount', CASE WHEN l.to_account = acct THEN l.amount ELSE -l.amount END,
      'counterparty', CASE WHEN l.to_account = acct THEN l.from_account ELSE l.to_account END,
      'tick_number', (SELECT tick_number FROM tycoon.ticks WHERE id = l.tick_id),
      'parcel_id', l.parcel_id,
      'parcel_name', (SELECT name FROM tycoon.parcels WHERE id = l.parcel_id)) ORDER BY l.id DESC)
    FROM (SELECT * FROM tycoon.ledger
           WHERE world_id = v_world AND (to_account = acct OR from_account = acct)
           ORDER BY id DESC LIMIT LEAST(COALESCE((p ->> 'limit')::INT, 50), 200)) l), '[]'::JSONB);
END $$;

CREATE OR REPLACE FUNCTION public.tycoon_my_parcels(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
DECLARE v_pl UUID := tycoon.auth_player(p);
BEGIN
  RETURN COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'id', pa.id, 'name', pa.name, 'suburb', pa.suburb, 'c_lon', pa.c_lon, 'c_lat', pa.c_lat,
      'land_value', pa.land_value, 'improvement_value', pa.improvement_value,
      'slots_total', pa.slots_total,
      'slots_used', COALESCE((SELECT SUM(slots_used) FROM tycoon.improvements WHERE parcel_id = pa.id), 0))
      ORDER BY pa.land_value + pa.improvement_value DESC)
    FROM tycoon.parcels pa WHERE pa.owner_id = v_pl), '[]'::JSONB);
END $$;

CREATE OR REPLACE FUNCTION public.tycoon_leaderboard(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
DECLARE v_world UUID := (p ->> 'world_id')::UUID;
BEGIN
  RETURN COALESCE((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.net_worth DESC) FROM (
    SELECT pl.id AS player_id, pl.handle,
           COALESCE(b.balance, 0) AS balance,
           COALESCE(a.n, 0) AS parcel_count,
           COALESCE(a.land, 0) AS land_value,
           COALESCE(a.impr, 0) AS improvement_value,
           COALESCE(lo.loan, 0) AS loan_outstanding,
           COALESCE(b.balance, 0) + COALESCE(a.land, 0) + COALESCE(a.impr, 0) - COALESCE(lo.loan, 0) AS net_worth
      FROM tycoon.players pl
      LEFT JOIN tycoon.balances b ON b.world_id = v_world AND b.account = tycoon.player_account(pl.id)
      LEFT JOIN (SELECT owner_id, count(*) AS n, SUM(land_value) AS land, SUM(improvement_value) AS impr
                   FROM tycoon.parcels WHERE world_id = v_world AND owner_id IS NOT NULL
                  GROUP BY owner_id) a ON a.owner_id = pl.id
      LEFT JOIN (SELECT acct, SUM(delta) AS loan FROM (
                   SELECT to_account AS acct, amount AS delta FROM tycoon.ledger
                    WHERE world_id = v_world AND reason = 'loan'
                   UNION ALL
                   SELECT from_account, -amount FROM tycoon.ledger
                    WHERE world_id = v_world AND reason = 'loan_repayment') l GROUP BY acct) lo
             ON lo.acct = tycoon.player_account(pl.id)
     WHERE pl.world_id = v_world
     ORDER BY net_worth DESC
     LIMIT 20) x), '[]'::JSONB);
END $$;

CREATE OR REPLACE FUNCTION public.tycoon_events(p JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = tycoon, extensions, public AS $$
BEGIN
  RETURN COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'id', e.id, 'kind', e.kind, 'created_at', e.created_at, 'data', e.data,
      'handle', pl.handle, 'player_id', e.player_id,
      'parcel_id', e.parcel_id, 'parcel_name', pa.name, 'suburb', pa.suburb,
      'c_lon', pa.c_lon, 'c_lat', pa.c_lat) ORDER BY e.id DESC)
    FROM (SELECT * FROM tycoon.events WHERE world_id = (p ->> 'world_id')::UUID
           ORDER BY id DESC LIMIT LEAST(COALESCE((p ->> 'limit')::INT, 30), 100)) e
    LEFT JOIN tycoon.players pl ON pl.id = e.player_id
    LEFT JOIN tycoon.parcels pa ON pa.id = e.parcel_id), '[]'::JSONB);
END $$;

-- >>> 004_security.sql
-- =====================================================================
-- Tycoon: access control.
-- Clients get EXECUTE on the public.tycoon_* API functions and nothing
-- else. The `tycoon` schema (tables + internal functions) is unreachable
-- for the Supabase `anon`/`authenticated` roles, and RLS is enabled on
-- every table with no policies, so even a misplaced grant can't expose a
-- row or allow a direct write.
-- =====================================================================

ALTER TABLE tycoon.rulesets       ENABLE ROW LEVEL SECURITY;
ALTER TABLE tycoon.worlds         ENABLE ROW LEVEL SECURITY;
ALTER TABLE tycoon.accounts       ENABLE ROW LEVEL SECURITY;
ALTER TABLE tycoon.sessions       ENABLE ROW LEVEL SECURITY;
ALTER TABLE tycoon.players        ENABLE ROW LEVEL SECURITY;
ALTER TABLE tycoon.parcels        ENABLE ROW LEVEL SECURITY;
ALTER TABLE tycoon.building_types ENABLE ROW LEVEL SECURITY;
ALTER TABLE tycoon.improvements   ENABLE ROW LEVEL SECURITY;
ALTER TABLE tycoon.ticks          ENABLE ROW LEVEL SECURITY;
ALTER TABLE tycoon.ledger         ENABLE ROW LEVEL SECURITY;
ALTER TABLE tycoon.events         ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON SCHEMA tycoon FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA tycoon FROM PUBLIC;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA tycoon FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA tycoon FROM PUBLIC;

DO $$
DECLARE
  r TEXT;
  f RECORD;
BEGIN
  FOREACH r IN ARRAY ARRAY['anon', 'authenticated'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
      EXECUTE format('REVOKE ALL ON SCHEMA tycoon FROM %I', r);
      EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA tycoon FROM %I', r);
      EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA tycoon FROM %I', r);
      EXECUTE format('REVOKE ALL ON ALL FUNCTIONS IN SCHEMA tycoon FROM %I', r);
      FOR f IN SELECT p.oid::regprocedure AS sig FROM pg_proc p
                 JOIN pg_namespace n ON n.oid = p.pronamespace
                WHERE n.nspname = 'public' AND p.proname LIKE 'tycoon\_%' LOOP
        EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO %I', f.sig, r);
      END LOOP;
    END IF;
  END LOOP;
END $$;

